using System;
using System.Drawing;
using System.Linq;
using System.Collections.Generic;
using System.Text.RegularExpressions;
using System.Runtime.InteropServices;
using System.Windows.Forms;
namespace Overclock {
 sealed partial class MainWindow {
  BenchmarkResults results;StorageCapacity capacitySnapshot;string capacityRaw="";
  [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr window,int attribute,ref int value,int size);
  protected override void OnHandleCreated(EventArgs args){base.OnHandleCreated(args);try{int dark=1;DwmSetWindowAttribute(Handle,20,ref dark,4);}catch{}}
  void BuildTabs(){foreach(Control c in tabs.Controls.Cast<Control>().ToArray())c.Dispose();tabs.Controls.Clear();string group=new[]{"CPU","GPU","Memory","Storage","Drive Health","Sensors","Inventory","Network"}.Contains(page)?"Hardware":page.EndsWith("Benchmark")?"Storage tests":page=="GPU Stress Test"?"GPU stress":page;foreach(var b in navButtons){b.Value.Selected=b.Key==group;b.Value.Invalidate();}string[] names=group=="Hardware"?new[]{"CPU","GPU","Memory","Storage","Drive Health","Sensors","Inventory"}:group=="Storage tests"?new[]{"Disk Benchmark","AS SSD Benchmark","Copy Benchmark","Compression Benchmark"}:new string[0];tabs.Visible=!compact&&names.Length>0;foreach(string name in names){string destination=name;var b=(ModernButton)Theme.Button(name.Replace(" Benchmark",""));b.Width=group=="Hardware"?(name=="Drive Health"?145:name=="Inventory"?110:100):name=="Compression Benchmark"?155:120;b.Font=Theme.Face(11,FontStyle.Bold|FontStyle.Italic);b.Selected=page==name;b.Click+=(s,e)=>Navigate(destination);tabs.Controls.Add(b);}subtitle.Text=page=="RGB Studio"?"Control and synchronize supported local lighting. No automatic writes.":page=="Display Studio"?"Manage monitor brightness, colour and Windows profiles.":compact?"Live hardware at a glance":page=="Overview"?"Your system, in focus.   Live telemetry and recent activity.":group=="Storage tests"?"Choose a drive and preset. Advanced settings stay out of the way.":page=="Sensors"?"Explore hardware readings. Select a row to see its history.":page=="Drive Health"?"Drive condition, temperatures and warnings — without the data dump.":page=="GPU Stress Test"?"Independent OpenGL workload with temperature protection.":page=="Reports"?"Your benchmark history. Compare matching workloads and export results.":"Live hardware information, clearly organized.";results=null;}
  void UpdateResultContext(object sender,EventArgs args){if(results!=null&&!results.IsDisposed)results.SetContext(disks.Text,page=="Copy Benchmark"?"Copy":profile.Text,size.Text,duration.Text,repeats.Text);}
  string Metric(string key,string prefix){string l=sources[key].Value.Split('\n').FirstOrDefault(v=>v.StartsWith(prefix));return l==null?"—":l.Substring(prefix.Length).Trim().TrimEnd('\r');}
  HardwareIdentity identity=new HardwareIdentity();string identityRaw="",lastNetwork="";DateTime lastNetworkUpdate;
  bool Fresh(string key){var c=sources[key];return c.Updated!=DateTime.MinValue&&(DateTime.UtcNow-c.Updated).TotalSeconds<Math.Max(20,c.Interval+c.Timeout*2)&&string.IsNullOrEmpty(c.Error);}
  void UpdateCards(){
   string ids=sources["Identity"].Value;if(ids!=identityRaw){identityRaw=ids;try{identity=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<HardwareIdentity>(ids);}catch{identity=new HardwareIdentity();}}
   string incoming=sources["Capacity"].Value;if(incoming!=capacityRaw){capacityRaw=incoming;try{capacitySnapshot=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<StorageCapacity>(incoming);}catch{capacitySnapshot=null;}}
   string network=sources["Network"].Value.Split('\n').FirstOrDefault()??"";var net=Regex.Match(network,@"RX ([0-9.]+) KiB/s\s+TX ([0-9.]+)");var type=Regex.Match(network,@"Type=([^;]+);Physical=([^;]+);State=([^;]+);Route=([^\]]+)");
   if(sources["Network"].Updated!=lastNetworkUpdate){lastNetworkUpdate=sources["Network"].Updated;if(lastNetwork!=network.Split(new[]{"  "},StringSplitOptions.None)[0])networkHistory.Clear();lastNetwork=network.Split(new[]{"  "},StringSplitOptions.None)[0];float value;if(net.Success&&float.TryParse(net.Groups[1].Value,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)){networkHistory.Enqueue(value);while(networkHistory.Count>90)networkHistory.Dequeue();}}
   foreach(var pair in tiles){string key=pair.Key;var tile=pair.Value;string primary="—",unit="",device="",secondary="",foot="Open details  →",ring="—",art=null;float level=-1;float[] series=new float[0];
    if(key=="CPU"||key=="GPU"){
     string[] lines=sources[key].Value.Split('\n');device=key=="CPU"?lines.Skip(1).FirstOrDefault()??"Detecting processor":lines.FirstOrDefault()??"Detecting graphics";
     if(key=="GPU"&&device.TrimStart().StartsWith("Name",StringComparison.OrdinalIgnoreCase)){var model=Regex.Match(sources[key].Value,@"Name\s*:\s*([^\r\n]+)");device=model.Success?model.Groups[1].Value:"Graphics adapter unavailable";}
     if(Fresh(key)){float load=ReadMetric(sources[key].Value,key=="CPU"?"CPU load":"Load");primary=load>=0?load.ToString("0")+"%":"—";unit="UTILIZATION";if(key=="GPU"){ring=Metric("GPU","Temperature").Replace("°C","°").Replace(" ","");secondary="Power "+Metric("GPU","Power")+"   ·   "+Metric("GPU","Clock");float t;if(float.TryParse(Regex.Match(ring,@"[0-9.]+").Value,out t))level=t;art=DashboardArt.Gpu(device.Trim(),identity.Gpus);}else{bool sensorFresh=(DateTime.UtcNow-sensorClient.Snapshot.Utc).TotalSeconds<30;var t=sensorFresh?sensorClient.Snapshot.Sensors.FirstOrDefault(v=>v.Id.Contains("cpu")&&v.Type=="Temperature"&&v.Value.HasValue&&v.Value.Value>0&&v.Value.Value<120):null;ring=t==null?"N/A":t.Value.Value.ToString("0")+"°";level=t==null?-1:t.Value.Value;secondary=Environment.ProcessorCount+" logical processors · "+(t==null?"Temperature unavailable":"Live temperature");art=DashboardArt.Cpu(identity.CpuVendor);}series=(key=="CPU"?cpuHistory:gpuHistory).ToArray();foot="LIVE   ·   Utilization history";}else{unit="Reading unavailable";secondary="Waiting for fresh telemetry";ring="N/A";}
    }else if(key=="Memory"){
     art="memory";var m=Regex.Match(Metric("CPU","RAM"),@"([0-9.]+) / ([0-9.]+)");if(Fresh("CPU")&&m.Success){primary=m.Groups[1].Value;unit="of "+m.Groups[2].Value+" GiB used";float used,total;if(float.TryParse(m.Groups[1].Value,out used)&&float.TryParse(m.Groups[2].Value,out total)&&total>0){level=100*used/total;ring=level.ToString("0")+"%";}}device="System memory";secondary="Capacity, speed and module details";var memoryLoad=sensorClient.Snapshot.Sensors.FirstOrDefault(v=>v.Id.Contains("ram")&&v.Type=="Load");Queue<float> memorySamples;if(memoryLoad!=null&&sensorClient.History.TryGetValue(memoryLoad.Id,out memorySamples))series=memorySamples.ToArray();
    }else if(key=="Storage"){
     tile.Capacity=Fresh("Capacity")?capacitySnapshot:null;art=DashboardArt.Storage(tile.Capacity);primary=tile.Capacity==null?"—":StorageFormat.Size(tile.Capacity.PhysicalBytes);unit="total installed storage";device="Physical drives";secondary=tile.Capacity==null?"Waiting for fresh capacity data":"Used and free space across mounted volumes";ring="";
    }else if(key=="Network"){
     if(Fresh("Network")&&net.Success){primary=net.Groups[1].Value;unit="KiB/s receiving";secondary="Sending "+net.Groups[2].Value+" KiB/s";device=lastNetwork;art=type.Success?DashboardArt.Network(type.Groups[1].Value,type.Groups[3].Value,type.Groups[2].Value=="True"):null;foot=type.Success?(type.Groups[1].Value=="Wireless80211"?"Wi-Fi":type.Groups[1].Value)+" · "+type.Groups[4].Value:"Active adapter · Open details →";series=networkHistory.ToArray();}else{unit="No current traffic reading";device=network.Contains("No active")?"Disconnected":"Network unavailable";secondary="Waiting for an active adapter";}ring="NET";
    }else{art="sensors";bool fresh=(DateTime.UtcNow-sensorClient.Snapshot.Utc).TotalSeconds<30;primary=fresh?sensorClient.Snapshot.Sensors.Count.ToString():"—";unit="sensor channels";device="Hardware sensors";secondary=fresh?"Temperatures, clocks, fans and power":"Waiting for fresh sensor data";ring=fresh?"LIVE":"N/A";}
    tile.ArtKey=art;tile.Set(key,primary,unit,device.Trim(),secondary,foot,level,ring,series);
   }
  }
 }
}